def compute(vars):
    net_income = vars["Net Income"]
    sales_revenue = vars["Sales Revenue"]

    if sales_revenue == 0:
        return None

    net_profit_margin = net_income / sales_revenue

    return {
        "value": net_profit_margin,
        "trace": {
            "Net Income": net_income,
            "Sales Revenue": sales_revenue,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
